#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ItemType {
    Sword,
    Amulet,
    Staff,
    Potion,
    Rune,
}

#[derive(Clone, Copy, Debug)]
pub struct Item {
    pub item_type: ItemType,
}

impl Item {
    pub fn new(item_type: ItemType) -> Self {
        Self { item_type }
    }
}

const PROCESSING_FEE: u64 = 5;

fn base_premium(item_type: ItemType) -> u64 {
    match item_type {
        ItemType::Sword => 100,
        ItemType::Amulet => 60,
        ItemType::Staff => 80,
        ItemType::Potion => 40,
        ItemType::Rune => 25,
    }
}

pub fn quote(items: &[Item]) -> u64 {
    let policy_base_premium: u64 = items.iter().map(|item| base_premium(item.item_type)).sum();
    policy_base_premium + PROCESSING_FEE
}

